// Attendance calculators on the tool pages (generated by tools/build_seo_pages.py).
//
// Each calculator on a page is a [data-widget] element; the page supplies its
// wording in window.CALC_TEXT before loading this file. A wording entry is a
// string, or {one, other} where the number decides which one is used. The
// maths follows lib/features/reports/attendance_report_model.dart in the app
// repository (bunkable, classesToTarget), so the site and the app always give
// the same answer for the same numbers.
(function () {
  var T = window.CALC_TEXT;
  // Guards against 74.99999… from floating point turning into one class less.
  var EPS = 1e-9;

  function text(key, n) {
    var value = T[key];
    return typeof value === 'string' ? value : (n === 1 ? value.one : value.other);
  }
  function fill(template, values) {
    return template.replace(/\{(\w+)\}/g, function (_, key) { return values[key]; });
  }
  // Rounds down, so a percentage just under the target never reads as the target.
  function fmt(value) {
    return (Math.floor(value * 100 + EPS) / 100).toLocaleString(document.documentElement.lang);
  }
  function isCount(value) { return !isNaN(value) && value >= 0 && value % 1 === 0; }

  // How many more classes may be missed while staying at target.
  function canMiss(held, attended, target) {
    return Math.max(0, Math.floor(attended * 100 / target - held + EPS));
  }
  // How many classes in a row must be attended to get back to target.
  function mustAttend(held, attended, target) {
    var ratio = target / 100;
    return Math.max(0, Math.ceil((ratio * held - attended) / (1 - ratio) - EPS));
  }

  // Each returns [headline, detail, tone], or a string for invalid input.
  var KINDS = {
    standing: function (v) {
      if (v.held < 1) return text('wholeNumbers');
      if (v.attended > v.held) return text('attendedTooMany');
      var now = v.attended * 100 / v.held;
      var current = fill(text('current'), { pct: fmt(now) });
      if (now + EPS >= v.target) {
        var miss = canMiss(v.held, v.attended, v.target);
        if (miss === 0) {
          return [text('atEdge'), fill(text('atEdgeDetail'), { current: current, target: fmt(v.target) }), 'edge'];
        }
        return [fill(text('canMiss', miss), { n: miss, target: fmt(v.target) }),
          fill(text('canMissDetail'), { current: current, pct: fmt(v.attended * 100 / (v.held + miss)) }), 'good'];
      }
      if (v.target >= 100) return [text('unreachable'), current, 'bad'];
      var need = mustAttend(v.held, v.attended, v.target);
      return [fill(text('mustAttend', need), { n: need, target: fmt(v.target) }),
        fill(text('mustAttendDetail'), { current: current, pct: fmt((v.attended + need) * 100 / (v.held + need)) }), 'bad'];
    },

    plan: function (v) {
      if (v.total < 1) return text('wholeNumbers');
      var miss = Math.max(0, Math.floor(v.total * (1 - v.target / 100) + EPS));
      return [fill(text('planMiss', miss), { n: miss, total: v.total }),
        fill(text('planDetail'), { attend: v.total - miss, total: v.total }), 'good'];
    },

    whatif: function (v) {
      if (v.held < 1) return text('wholeNumbers');
      if (v.attended > v.held) return text('attendedTooMany');
      var after = v.attended * 100 / (v.held + v.skip);
      var most = canMiss(v.held, v.attended, v.target);
      var ok = after + EPS >= v.target;
      return [fill(text('whatif', v.skip), { n: v.skip, pct: fmt(after) }),
        fill(text(ok ? 'whatifAbove' : 'whatifBelow'), { target: fmt(v.target), m: most }), ok ? 'good' : 'bad'];
    },

    recover: function (v) {
      if (v.held + v.remaining < 1) return text('wholeNumbers');
      if (v.attended > v.held) return text('attendedTooMany');
      var final = v.held + v.remaining;
      var need = Math.max(0, Math.ceil(v.target / 100 * final - v.attended - EPS));
      if (need > v.remaining) {
        return [fill(text('recoverImpossible'), { rem: v.remaining, pct: fmt((v.attended + v.remaining) * 100 / final) }),
          fill(text('recoverImpossibleDetail'), { target: fmt(v.target) }), 'bad'];
      }
      if (need === 0) return [fill(text('recoverSafe'), { rem: v.remaining, target: fmt(v.target) }), '', 'good'];
      return [fill(text('recover', need), { n: need, rem: v.remaining }),
        fill(text('recoverDetail'), { m: v.remaining - need, target: fmt(v.target) }), 'good'];
    },

    semester: function (v) {
      if (v.weeks < 1 || v.per_week < 1) return text('wholeNumbers');
      var scheduled = v.weeks * v.per_week;
      if (v.cancelled >= scheduled) return text('semesterCancelled');
      var total = scheduled - v.cancelled;
      var miss = Math.max(0, Math.floor(total * (1 - v.target / 100) + EPS));
      var attend = total - miss;
      return [fill(text('semesterMiss'), {miss: miss, attend: attend, total: total}),
        fill(text('semesterSummary'), {weeks: v.weeks, perWeek: v.per_week, cancelled: v.cancelled, total: total}) + ' ' +
        fill(text('semesterWeeks'), {weeks: fmt(miss / v.per_week), perWeek: v.per_week}), 'good'];
    },

    hours: function (v) {
      if (v.hours_total < 1 || v.hours_per_class < 1) return text('wholeNumbers');
      if (v.hours_missed > v.hours_total) return text('hoursMissedTooMany');
      var allowed = Math.max(0, Math.floor(v.hours_total * (1 - v.target / 100) + EPS));
      var remaining = allowed - v.hours_missed;
      if (remaining < 0) return [fill(text('hoursOver'), {over: -remaining, allowed: allowed}),
        fill(text('hoursOverDetail'), {missed: v.hours_missed, target: fmt(v.target)}), 'bad'];
      var meetings = Math.floor(remaining / v.hours_per_class + EPS);
      return [fill(text('hoursRemaining'), {remaining: remaining, meetings: meetings}),
        fill(text('hoursDetail'), {allowed: allowed, total: v.hours_total, missed: v.hours_missed, perClass: v.hours_per_class}), 'good'];
    }
  };

  function attachSubjects(root) {
    var box = root.querySelector('.result');
    var rows = root.querySelector('.subject-rows');
    var targetInput = root.querySelector('input[name="target"]');
    function addResult(value) {
      var line = document.createElement('p');
      line.textContent = value;
      root.querySelector('.subject-results').appendChild(line);
    }
    function run() {
      var target = Number(targetInput.value.trim());
      var blank = targetInput.value.trim() === '';
      var invalidTarget = isNaN(target) || target <= 0 || target > 100;
      var invalidCount = false, attendedTooMany = false;
      var subjects = [];
      rows.querySelectorAll('.subject-row').forEach(function (row, index) {
        var heldInput = row.querySelector('input[name="held"]');
        var attendedInput = row.querySelector('input[name="attended"]');
        var heldRaw = heldInput.value.trim();
        var attendedRaw = attendedInput.value.trim();
        if (heldRaw === '' || attendedRaw === '') blank = true;
        var held = Number(heldRaw), attended = Number(attendedRaw);
        if (!isCount(held) || held < 1 || !isCount(attended)) invalidCount = true;
        if (attended > held) attendedTooMany = true;
        subjects.push({name: row.querySelector('input[name="subject"]').value.trim() || fill(text('subjectFallback'), {n: index + 1}), held: held, attended: attended});
      });
      if (blank) { box.hidden = true; return; }
      if (invalidTarget || invalidCount || attendedTooMany) {
        box.hidden = false; box.dataset.tone = 'warn';
        box.querySelector('.result-headline').textContent = invalidTarget ? text('targetRange') : invalidCount ? text('wholeNumbers') : text('attendedTooMany');
        box.querySelector('.result-detail').textContent = '';
        root.querySelector('.subject-results').textContent = '';
        return;
      }
      var totalHeld = 0, totalAttended = 0, below = [];
      var resultList = root.querySelector('.subject-results');
      resultList.textContent = '';
      subjects.forEach(function (subject) {
        totalHeld += subject.held; totalAttended += subject.attended;
        var pct = subject.attended * 100 / subject.held;
        if (pct + EPS >= target) {
          var miss = canMiss(subject.held, subject.attended, target);
          addResult(fill(text(miss ? 'subjectCanMiss' : 'subjectAtEdge'), {name: subject.name, pct: fmt(pct), n: miss}));
        } else {
          below.push(subject.name);
          var need = target >= 100 ? null : mustAttend(subject.held, subject.attended, target);
          addResult(fill(text(need === null ? 'subjectUnreachable' : 'subjectMustAttend'), {name: subject.name, pct: fmt(pct), n: need}));
        }
      });
      var overall = totalAttended * 100 / totalHeld;
      box.hidden = false;
      box.dataset.tone = below.length ? 'bad' : 'good';
      box.querySelector('.result-headline').textContent = fill(text('subjectsOverall'), {pct: fmt(overall), attended: totalAttended, held: totalHeld});
      var detail = '';
      if (overall + EPS >= target && below.length) detail = fill(text(below.length === 1 ? 'subjectsWarning' : 'subjectsWarnings'), {names: below.join(', '), target: fmt(target)});
      else if (overall + EPS < target) detail = fill(text('subjectsBelow'), {target: fmt(target)});
      box.querySelector('.result-detail').textContent = detail;
    }
    root.querySelector('.add-subject').addEventListener('click', function () {
      var row = rows.querySelector('.subject-row').cloneNode(true);
      row.querySelector('input[name="subject"]').value = '';
      row.querySelector('input[name="held"]').value = '';
      row.querySelector('input[name="attended"]').value = '';
      rows.appendChild(row); run();
    });
    rows.addEventListener('click', function (event) {
      if (!event.target.classList.contains('remove-subject')) return;
      if (rows.children.length > 1) event.target.closest('.subject-row').remove();
      run();
    });
    root.addEventListener('input', run);
    run();
  }

  function attachCountdown(root) {
    var box = root.querySelector('.result');
    var dateInput = root.querySelector('input[name="exam_date"]');
    var exclude = root.querySelector('input[name="exclude_sundays"]');
    var today = new Date();
    var todayUtc = Date.UTC(today.getFullYear(), today.getMonth(), today.getDate());
    if (!dateInput.value) {
      var initial = new Date(todayUtc + Number(root.dataset.daysAhead || 30) * 86400000);
      dateInput.value = initial.toISOString().slice(0, 10);
    }
    function run() {
      if (!dateInput.value) { box.hidden = true; return; }
      var parts = dateInput.value.split('-').map(Number);
      var examUtc = Date.UTC(parts[0], parts[1] - 1, parts[2]);
      var days = Math.round((examUtc - todayUtc) / 86400000);
      box.hidden = false;
      if (days < 0) {
        box.dataset.tone = 'bad'; box.querySelector('.result-headline').textContent = text('countdownPast');
        box.querySelector('.result-detail').textContent = ''; return;
      }
      if (days === 0) {
        box.dataset.tone = 'edge'; box.querySelector('.result-headline').textContent = text('countdownToday');
        box.querySelector('.result-detail').textContent = fill(text('countdownStudy'), {study: 0}); return;
      }
      var study = days;
      if (exclude.checked) {
        var fullWeeks = Math.floor(days / 7), remainder = days % 7, sundays = fullWeeks;
        var tomorrowDay = new Date(todayUtc + 86400000).getUTCDay();
        for (var i = 0; i < remainder; i++) if ((tomorrowDay + i) % 7 === 0) sundays++;
        study -= sundays;
      }
      box.dataset.tone = 'good';
      box.querySelector('.result-headline').textContent = fill(text('countdownHeadline'), {days: days});
      box.querySelector('.result-detail').textContent = fill(text('countdownDetail'), {weeks: Math.floor(days / 7), extra: days % 7}) + ' ' + fill(text('countdownStudy'), {study: study});
    }
    root.addEventListener('input', run); root.addEventListener('change', run); run();
  }

  function attachCredits(root) {
    var box = root.querySelector('.result');
    var creditsInput = root.querySelector('input[name="credits"]');
    var weeksInput = root.querySelector('input[name="weeks"]');
    var systemInput = root.querySelector('select[name="system"]');
    var customField = root.querySelector('.custom-hours-field');
    var customInput = root.querySelector('input[name="hours_per_credit"]');
    function run() {
      var credits = Number(creditsInput.value.trim());
      var weeks = Number(weeksInput.value.trim());
      var custom = Number(customInput.value.trim());
      var system = systemInput.value;
      customField.hidden = system !== 'custom';
      if (creditsInput.value.trim() === '' || weeksInput.value.trim() === '' ||
          (system === 'custom' && customInput.value.trim() === '')) {
        box.hidden = true; return;
      }
      if (!isFinite(credits) || credits <= 0 || !isCount(weeks) || weeks < 1 ||
          (system === 'custom' && (!isFinite(custom) || custom <= 0))) {
        box.hidden = false; box.dataset.tone = 'warn';
        box.querySelector('.result-headline').textContent = text('creditsPositive');
        box.querySelector('.result-detail').textContent = ''; return;
      }
      var headline, detail;
      if (system === 'us') {
        var usTotal = credits * 45;
        var usWeekly = usTotal / weeks;
        var usOutside = credits * 30 / weeks;
        headline = fill(text('creditsUs'), {weekly: fmt(usWeekly), outside: fmt(usOutside)});
        detail = fill(text('creditsUsDetail'), {credits: fmt(credits), total: fmt(usTotal), weeks: weeks});
      } else if (system === 'ects') {
        var lowTotal = credits * 25, highTotal = credits * 30;
        headline = fill(text('creditsEcts'), {low: fmt(lowTotal / weeks), high: fmt(highTotal / weeks)});
        detail = fill(text('creditsEctsDetail'), {credits: fmt(credits), low: fmt(lowTotal), high: fmt(highTotal), weeks: weeks});
      } else {
        var total = credits * custom;
        headline = fill(text('creditsCustom'), {weekly: fmt(total / weeks)});
        detail = fill(text('creditsCustomDetail'), {credits: fmt(credits), perCredit: fmt(custom), total: fmt(total), weeks: weeks});
      }
      box.hidden = false; box.dataset.tone = 'good';
      box.querySelector('.result-headline').textContent = headline;
      box.querySelector('.result-detail').textContent = detail;
    }
    root.addEventListener('input', run); root.addEventListener('change', run); run();
  }

  function attach(root) {
    var calculate = KINDS[root.dataset.widget];
    var box = root.querySelector('.result');
    function run() {
      var v = {};
      var blank = false;
      var counts = true;
      root.querySelectorAll('input').forEach(function (input) {
        var raw = input.value.trim();
        if (raw === '') blank = true;
        v[input.name] = Number(raw);
        if (input.name !== 'target' && !isCount(v[input.name])) counts = false;
      });
      if (blank) { box.hidden = true; return; }
      var result = !counts ? text('wholeNumbers')
        : (isNaN(v.target) || v.target <= 0 || v.target > 100) ? text('targetRange')
        : calculate(v);
      if (typeof result === 'string') result = [result, '', 'warn'];
      box.hidden = false;
      box.dataset.tone = result[2];
      box.querySelector('.result-headline').textContent = result[0];
      box.querySelector('.result-detail').textContent = result[1];
    }
    root.addEventListener('input', run);
    run();
  }

  document.querySelectorAll('[data-widget]').forEach(function (root) {
    if (root.dataset.widget === 'subjects') attachSubjects(root);
    else if (root.dataset.widget === 'countdown') attachCountdown(root);
    else if (root.dataset.widget === 'credits') attachCredits(root);
    else attach(root);
  });
})();
